import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import LinkButton from 'flarum/common/components/LinkButton';
import registerBlocks from './blocks';
app.initializers.add('ernestdefoe-roster', () => {
  // The crest wall, offered to Page Builder. Registration only.
  registerBlocks();

  // Code-split: each page loads when someone opens it, not with every page.
  app.routes['roster.index'] = {
    path: '/roster',
    component: () => import(/* webpackChunkName: 'forum/components/RosterIndexPage', webpackMode: 'lazy-once' */ './components/RosterIndexPage')
  };
  app.routes['roster.team'] = {
    path: '/roster/:slug',
    component: () => import(/* webpackChunkName: 'forum/components/RosterTeamPage', webpackMode: 'lazy-once' */ './components/RosterTeamPage')
  };
  app.routes['roster.player'] = {
    path: '/roster/:slug/:player',
    component: () => import(/* webpackChunkName: 'forum/components/RosterPlayerPage', webpackMode: 'lazy-once' */ './components/RosterPlayerPage')
  };

  /*
   * A place to click, in the nav every other page uses.
   *
   * 🚨 `IndexSidebar`, not `IndexPage`. Flarum 2 moved the index nav into its
   * own component, and extending the old one is not an error — the callback is
   * simply attached to a `navItems` nobody calls. The link was built, styled
   * and translated, and the only route to the roster was typing the URL.
   */
  extend(IndexSidebar.prototype, 'navItems', function (items) {
    items.add('roster', m(LinkButton, {
      href: app.route('roster.index'),
      icon: "fas fa-users"
    }, app.translator.trans('ernestdefoe-roster.forum.title')), -10);
  });
});flarum.reg.addChunkModule('ernestdefoe-roster:forum/components/RosterIndexPage', '374', 'ernestdefoe-roster', 'forum/components/RosterIndexPage');
flarum.reg.addChunkModule('ernestdefoe-roster:forum/components/RosterIndexPage', '374', 'ernestdefoe-roster', 'forum/waymark');
flarum.reg.addChunkModule('ernestdefoe-roster:forum/components/RosterTeamPage', '101', 'ernestdefoe-roster', 'forum/components/RosterTeamPage');
flarum.reg.addChunkModule('ernestdefoe-roster:forum/components/RosterPlayerPage', '465', 'ernestdefoe-roster', 'forum/components/RosterPlayerPage');